contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);

        uint beforeBalance = address(c).balance;
        require(amount < beforeBalance);

        c.multiplicate{value: amount}(recipient); if (__ESBMC_reverted()) return;

        uint afterBalance = address(c).balance;
        assert(afterBalance > 0);
    }

    receive() external payable {}
}

